"""
api/reprocesar.py  -  Vercel Python Serverless Function

Reprocesa en lote resoluciones de AUDIFONOS con el precio unitario x100.
Lee cada PDF, recalcula unitario = total // cantidad y regenera la resolución
en el formato oficial (Century Gothic / tabla sin color / pie "Año de la
Memoria"), corrigiendo solo el valor. Devuelve un ZIP con todas.

Fuentes incrustadas (subconjuntos): URW Gothic (=Century Gothic), Carlito
(=Calibri), Liberation Serif (=Times New Roman). Requiere pypdf (requirements.txt).

POST JSON: { "pdfs": [ {"nombre": "...", "base64": "<PDF b64>"}, ... ] }
Respuesta: { "ok": true, "zip_base64": "...", "resultados": [...], "errores": [...] }
"""
import json, base64, io, zipfile, re, os, tempfile
from http.server import BaseHTTPRequestHandler
from fpdf import FPDF
from pypdf import PdfReader

LOGO1_B64 = ""
LOGO2_B64 = ""
FONT_GOTHIC = ""
FONT_GOTHICB = ""
FONT_CARLITO = ""
FONT_CARLITOB = ""
FONT_TIMES = ""
FONT_TIMESB = ""


RGB_AZUL = (91, 155, 213)

XL, XR = 30, 180          # margenes izq/der (mm)

def _fmt(n): return "{:,}".format(int(n)).replace(",", ".")

_FONTDIR = os.path.join(tempfile.gettempdir(), "rpfonts")
def _ensure_fonts():
    os.makedirs(_FONTDIR, exist_ok=True)
    for nombre, b64 in [("gothic.ttf",FONT_GOTHIC),("gothicB.ttf",FONT_GOTHICB),
                        ("carlito.ttf",FONT_CARLITO),("carlitoB.ttf",FONT_CARLITOB),
                        ("times.ttf",FONT_TIMES),("times2B.ttf",FONT_TIMESB)]:
        p=os.path.join(_FONTDIR,nombre)
        if not os.path.exists(p):
            with open(p,"wb") as f: f.write(base64.b64decode(b64))
    return _FONTDIR

def _fonts(pdf):
    d=_ensure_fonts()
    pdf.add_font("gothic","",  os.path.join(d,"gothic.ttf"))
    pdf.add_font("gothic","B", os.path.join(d,"gothicB.ttf"))
    pdf.add_font("carlito","", os.path.join(d,"carlito.ttf"))
    pdf.add_font("carlito","B",os.path.join(d,"carlitoB.ttf"))
    pdf.add_font("times2","",  os.path.join(d,"times.ttf"))
    pdf.add_font("times2","B", os.path.join(d,"times2B.ttf"))

def _words(segmentos):
    out=[]
    for texto,estilo in segmentos:
        for p in texto.split(" "):
            if p=="": continue
            out.append((p,estilo))
    return out

def _parrafo(pdf, segmentos, indent=0, size=12, lh=5.8, gap_after=3.0, fam="gothic"):
    words=_words(segmentos)
    if not words: return
    pdf.set_font(fam,"",size); space_w=pdf.get_string_width(" ")
    def wof(w,e):
        pdf.set_font(fam, "B" if "B" in e else "", size); return pdf.get_string_width(w)
    lines=[]; cur=[]; cur_w=0.0; first=True; avail=XR-(XL+indent)
    for w,e in words:
        ww=wof(w,e); add=ww if not cur else space_w+ww
        if cur and cur_w+add>avail+0.01:
            lines.append((cur,first)); first=False; avail=XR-XL; cur=[(w,e,ww)]; cur_w=ww
        else:
            cur.append((w,e,ww)); cur_w+=add
    if cur: lines.append((cur,first))
    block_h=len(lines)*lh+gap_after
    if pdf.get_y()+block_h>277 and block_h<=250:
        pdf.add_page(); pdf.set_y(20)
    for idx,(line,is_first) in enumerate(lines):
        if pdf.get_y()+lh>277:
            pdf.add_page(); pdf.set_y(20)
        lx=(XL+indent) if is_first else XL
        avail=XR-lx; is_last=(idx==len(lines)-1); n=len(line)
        words_w=sum(w for _,_,w in line); extra=0.0
        if not (is_last or n==1):
            extra=(avail-words_w-(n-1)*space_w)/(n-1)
            if extra<0: extra=0.0
        x=lx; y=pdf.get_y()
        for j,(w,e,ww) in enumerate(line):
            pdf.set_font(fam,"B" if "B" in e else "",size)
            pdf.set_xy(x,y); pdf.cell(ww,lh,w)
            if "U" in e:
                yy=y+lh-1.0; pdf.set_line_width(0.4); pdf.line(x,yy,x+ww,yy)
            x+=ww
            if j<n-1:
                gap=space_w+extra; pdf.set_font(fam,"",size); pdf.set_xy(x,y); pdf.cell(gap,lh," "); x+=gap
        pdf.set_y(y+lh)
    if gap_after: pdf.ln(gap_after)

def _label_ct(pdf,texto,size,gap=0):
    pdf.set_font("gothic","B",size); pdf.set_x(XL)
    w=pdf.get_string_width(texto); y=pdf.get_y()
    pdf.cell(w,size*0.5,texto)
    pdf.line(XL,y+size*0.5-1.0,XL+w,y+size*0.5-1.0)   # subrayado
    pdf.ln(size*0.5+ (gap or 3))

def construir_resolucion(d, mostrar_firma=True):
    fecha=d["fecha"]; nro=d["nroRes"]; exp=d["nroExp"]; pac=d["paciente"]
    firmas=d["firmasCons"]; firma=d["firmaGan"]; cant=str(d["cantidad"])
    total=int(d["total"]); unit=int(d["unitario"]); letras=d["importeLetras"]
    pu=_fmt(unit)+",00"; pt=_fmt(total)+",00"

    pdf=FPDF(orientation="P",unit="mm",format="A4")
    pdf.set_margins(XL,18,210-XR); pdf.set_auto_page_break(auto=False)
    _fonts(pdf); pdf.add_page()

    # LOGOS (sin linea azul debajo)
    tmp=[]
    for b64,x,y,h in [(LOGO1_B64,32,17,8),(LOGO2_B64,128,17,15)]:
        f=tempfile.NamedTemporaryFile(suffix=".png",delete=False); f.write(base64.b64decode(b64)); f.close()
        pdf.image(f.name,x=x,y=y,h=h); tmp.append(f.name)
    for t in tmp: os.unlink(t)

    # FECHA
    pdf.set_xy(XL,35); pdf.set_font("gothic","",12)
    pdf.cell(XR-XL,6,f"San Miguel de Tucumán, {fecha}.",align="R"); pdf.ln(9)

    # TITULO
    pdf.set_font("gothic","B",14)
    pdf.set_x(XL); pdf.cell(XR-XL,7,f"Resolución Interna: Nº {nro}/DGPRIS.",align="C"); pdf.ln(6)
    pdf.set_x(XL); pdf.cell(XR-XL,7,"PROGRAMA INTEGRADO DE SALUD",align="C"); pdf.ln(8)

    # VISTO
    _label_ct(pdf,"VISTO:",11,gap=3)
    _parrafo(pdf,[("El ",""),(f"Expte. Nº {exp}","B"),(", por el que se solicita la compra de ",""),
                  ("AUDIFONOS","B"),(" para el paciente; ",""),(pac,"B"),(" y","")],indent=33,gap_after=3)

    # CONSIDERANDO
    _label_ct(pdf,"CONSIDERANDO:",11,gap=3)
    _parrafo(pdf,[("Que se encuentra agregada la documentación correspondiente, la misma esta cumplimentada y debidamente conformada.","")],indent=25)
    _parrafo(pdf,[("Que se adjunta presupuestos de la Firmas Comerciales; ",""),(f"{firmas}.-","B")],indent=25)
    _parrafo(pdf,[("Que la propuesta de ",""),(firma,"B"),(" resulto la más conveniente para el Estado.","")],indent=25)
    _parrafo(pdf,[("Que se adjunta Dictamen Jurídico con opinión favorable.","")],indent=25)
    _parrafo(pdf,[("Que se aprueba todo lo actuado por encuadrarse a las disposiciones legales vigentes, que rigen sobre materia de contrataciones, conforme a lo normado en la Res. Nº 388/SPS-05.","")],indent=25,lh=7.0)
    pdf.ln(2)

    # POR ELLO / RESUELVE
    pdf.set_font("gothic","B",12); pdf.set_x(XL); pdf.cell(XR-XL,6,"POR ELLO:",align="C"); pdf.ln(6)
    pdf.set_x(XL); pdf.cell(XR-XL,6,"LA GERENCIA ADMINISTRATIVA DEL PROGRAMA INTEGRADO DE SALUD",align="C"); pdf.ln(6)
    pdf.set_font("gothic","B",16); pdf.set_x(XL); pdf.cell(XR-XL,8,"RESUELVE:",align="C"); pdf.ln(9)

    # ART 1
    _parrafo(pdf,[("ARTICULO 1º:","BU"),(" Aprobar la compra de Audífonos, a favor de la firma ",""),
                  (firma,"B"),(" que se detalla a continuación:","")],indent=0,gap_after=3)

    # TABLA (Carlito, sin color) -> luego pasa a hoja 2 (como el modelo)
    _tabla(pdf, firma, cant, pu, pt)
    pdf.add_page(); pdf.set_y(20)

    # ART 2..5
    _parrafo(pdf,[("ARTICULO 2º:","BU"),(" Autorizar la compra al proveedor ",""),(firma,"B"),
                  (" , por el importe de ",""),(f"$ {pt}","B"),(f" ({letras})",""),
                  (" , y posterior emisión de la orden de pago respectiva.","")],gap_after=3)
    _parrafo(pdf,[("ARTICULO 3º:","BU"),(" Imputar la erogación por un importe total de ",""),(f"$ {pt}","B"),
                  (f" ({letras})",""),(", y posterior emisión de la orden de pago respectiva, a la Jurisdicción 67, Unidad de Organización 965- Recursos disponibles con los que cuenta el servicio-Finalidad/Función 314, Programa 19, Act. /Ob. 01 - Partida 200 – ",""),
                  ("Subpartida 297","B"),("– con Financiamiento del Recurso 10 Tesoro General de la Provincia, con cargo al ",""),
                  ("Presupuesto 2026","B"),(".-","")],gap_after=3)
    _parrafo(pdf,[("ARTICULO 4º:","BU"),(" Pase a control de Ley del Honorable Tribunal de Cuentas.","")],gap_after=3)
    _parrafo(pdf,[("ARTICULO 5º:","BU"),(" Comunicar y archivar. -","")],gap_after=3)

    # FIRMA + LINEA AZUL + PIE (Times, abajo de la ultima pagina)
    if mostrar_firma:
        pdf.set_font("times2","B",12)
        yf=206
        for ln_ in ["Firmado digitalmente:","C.P.N Mariela Agustina Castillo","Gerente Administrativo",
                    "Dirección Gral. Prog. Integrado de Salud","SI.PRO.SA"]:
            pdf.set_xy(XL,yf); pdf.cell(0,5,ln_); yf+=4.8
    pdf.set_draw_color(*RGB_AZUL); pdf.set_line_width(0.6); pdf.line(XL,234.7,178,234.7)
    pdf.set_draw_color(0,0,0)
    pdf.set_font("times2","",12)
    pdf.set_xy(XL,238); pdf.cell(0,5,"“2026 Año de la Memoria por: Golpe de Estado Cívico Militar de 1976, Cierre Masivo")
    pdf.set_xy(XL,242.8); pdf.cell(0,5,"de los Ingenios en 1966 y Cierre de tos Talleres Ferroviarios de Tafí Viejo en 1980\"")

    return bytes(pdf.output())

def _tabla(pdf, firma, cant, pu, pt):
    cols=[34,49.8,19.6,20.2,25.4]; x0=XL
    y=pdf.get_y()
    # keep-together de la tabla
    if y+34>277: pdf.add_page(); pdf.set_y(20); y=pdf.get_y()
    hh=11; dh=11; th=10
    pdf.set_draw_color(0,0,0); pdf.set_line_width(0.2)
    # encabezado
    pdf.set_font("carlito","B",11)
    hdrs=[["FIRMA"],["INSUMO"],["CANTIDAD"],["PRECIO","UNITARIO"],["PRECIO","TOTAL"]]
    x=x0
    for i,ls in enumerate(hdrs):
        pdf.rect(x,y,cols[i],hh)
        n=len(ls); ty=y+hh-1.5-n*4.6
        for t in ls:
            pdf.set_xy(x+1.3,ty); pdf.cell(cols[i]-1.6,4.6,t,align="L"); ty+=4.6
        x+=cols[i]
    # datos
    yd=y+hh
    x=x0
    # firma (Gothic 9, 2 lineas, centrado)
    pdf.rect(x,yd,cols[0],dh); pdf.set_font("gothic","",9)
    pdf.set_xy(x,yd+1.5); pdf.multi_cell(cols[0],4.2,firma,align="C"); x+=cols[0]
    # insumo
    pdf.rect(x,yd,cols[1],dh); pdf.set_font("carlito","",11)
    pdf.set_xy(x,yd+(dh-5)/2); pdf.cell(cols[1],5,"Audifonos",align="C"); x+=cols[1]
    # cantidad
    pdf.rect(x,yd,cols[2],dh); pdf.set_xy(x,yd+(dh-5)/2); pdf.cell(cols[2],5,cant,align="C"); x+=cols[2]
    # precio unitario ($ arriba, monto abajo, derecha)
    pdf.rect(x,yd,cols[3],dh)
    pdf.set_xy(x,yd+1.5); pdf.cell(cols[3]-2,4.6,"$",align="R")
    pdf.set_xy(x,yd+5.8); pdf.cell(cols[3]-2,4.6,pu,align="R"); x+=cols[3]
    # precio total
    pdf.rect(x,yd,cols[4],dh)
    pdf.set_xy(x,yd+1.5); pdf.cell(cols[4]-2,4.6,"$",align="R")
    pdf.set_xy(x,yd+5.8); pdf.cell(cols[4]-2,4.6,pt,align="R")
    # fila total
    yt=yd+dh; x=x0
    pdf.set_font("carlito","B",11)
    w4=sum(cols[:4]); pdf.rect(x0,yt,w4,th); pdf.set_xy(x0+1.3,yt+(th-5)/2); pdf.cell(30,5,"TOTAL")
    pdf.rect(x0+w4,yt,cols[4],th)
    pdf.set_xy(x0+w4,yt+1.2); pdf.cell(cols[4]-2,4.6,"$",align="R")
    pdf.set_xy(x0+w4,yt+5.5); pdf.cell(cols[4]-2,4.6,pt,align="R")
    pdf.set_xy(x0,yt+th)


# ----------------------------- EXTRACCION -----------------------------------
def _norm(t): return re.sub(r"\s+", " ", t).strip()

def extraer_datos(pdf_bytes):
    r = PdfReader(io.BytesIO(pdf_bytes))
    t = _norm("\n".join((p.extract_text() or "") for p in r.pages))
    if not re.search(r"AUDIFONOS|Aud[íi]fonos", t):
        raise ValueError("No parece una resolución de audífonos.")
    def buscar(pat, campo, g=1):
        m = re.search(pat, t)
        if not m: raise ValueError("No se pudo leer el campo: %s" % campo)
        return m.group(g).strip()
    d = {}
    d["fecha"]      = buscar(r"Tucum[áa]n,\s*(.+?)\.\s*Resoluci", "fecha")
    d["nroRes"]     = buscar(r"Resoluci[óo]n Interna:\s*N[ºo°]\s*([\w/]+?)/DGPRIS", "nroRes")
    d["nroExp"]     = buscar(r"Expte\.\s*N[ºo°]\s*(.+?)\s*,\s*por el que", "nroExp")
    d["paciente"]   = buscar(r"paciente;\s*(.+?)\s+y\s+CONSIDERANDO", "paciente")
    d["firmasCons"] = buscar(r"Firmas Comerciales\s*;\s*(.+?)\s*\.-", "firmasCons")
    d["firmaGan"]   = buscar(r"propuesta de\s+(.+?)\s+resulto", "firmaGan")
    d["cantidad"]   = int(buscar(r"Aud[íi]fonos\s+(\d+)\s+\$", "cantidad"))
    imp = re.search(r"por el importe de\s*\$\s*([\d.]+),\d{2}\s*\((.+?)\)", t)
    if not imp: raise ValueError("No se pudo leer el importe.")
    d["importeLetras"] = imp.group(2).strip()
    d["total"]      = int(imp.group(1).replace(".", ""))
    if d["cantidad"] <= 0: raise ValueError("Cantidad inválida.")
    d["unitario"]   = d["total"] // d["cantidad"]
    return d

def procesar(pdfs):
    resultados, errores = [], []
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as zf:
        for item in pdfs:
            nombre = (item.get("nombre") or "").strip() or "resolucion.pdf"
            try:
                b = base64.b64decode(item["base64"])
                d = extraer_datos(b)
                pdf_out = construir_resolucion(d)
                apellido = d["paciente"].split(",")[0].strip().replace(" ", "_")
                fname = "Resolucion_%s_%s.pdf" % (d["nroRes"], apellido or "SIN_NOMBRE")
                zf.writestr(fname, pdf_out)
                resultados.append({"nombre": nombre, "archivo": fname,
                    "nroRes": d["nroRes"], "paciente": d["paciente"],
                    "cantidad": d["cantidad"], "unitario": d["unitario"], "total": d["total"]})
            except Exception as ex:
                errores.append({"nombre": nombre, "error": str(ex)})
    return buf.getvalue(), resultados, errores

class handler(BaseHTTPRequestHandler):
    def _cors(self):
        self.send_header("Access-Control-Allow-Origin", "*")
        self.send_header("Access-Control-Allow-Methods", "POST, OPTIONS")
        self.send_header("Access-Control-Allow-Headers", "Content-Type")
    def _json(self, code, obj):
        self.send_response(code); self._cors()
        self.send_header("Content-Type", "application/json"); self.end_headers()
        self.wfile.write(json.dumps(obj).encode("utf-8"))
    def do_OPTIONS(self):
        self.send_response(204); self._cors(); self.end_headers()
    def do_POST(self):
        try:
            largo = int(self.headers.get("Content-Length", 0))
            data = json.loads(self.rfile.read(largo).decode("utf-8"))
            pdfs = data.get("pdfs")
            if not pdfs or not isinstance(pdfs, list):
                return self._json(400, {"ok": False, "error": "Falta la lista 'pdfs'."})
            zip_bytes, resultados, errores = procesar(pdfs)
            if not resultados:
                return self._json(422, {"ok": False, "error": "No se pudo procesar ningún PDF.", "errores": errores})
            return self._json(200, {"ok": True,
                "zip_base64": base64.b64encode(zip_bytes).decode("ascii"),
                "resultados": resultados, "errores": errores})
        except Exception as ex:
            return self._json(500, {"ok": False, "error": str(ex)})
